import requests
import json
from collections import defaultdict

BASE_URL = "http://81.10.121.99:81"

def get_token():
    url = f"{BASE_URL}/api/Users/Token/1"
    resp = requests.get(url)
    resp.raise_for_status()
    data = resp.json()
    # Assuming token is in a field like 'token' or 'accessToken'
    # Adjust based on actual response structure
    token = data.get('token') or data.get('accessToken') or data.get('Token')
    if not token:
        # Maybe the whole response is the token string?
        if isinstance(data, str):
            token = data
        else:
            # Try to find any string that looks like a JWT
            for v in data.values():
                if isinstance(v, str) and len(v) > 10 and '.' in v:
                    token = v
                    break
    return token

def fetch_all(url, token):
    headers = {'Authorization': f'Bearer {token}'} if token else {}
    resp = requests.get(url, headers=headers)
    resp.raise_for_status()
    return resp.json()

def main():
    try:
        token = get_token()
        print(f"Token acquired: {token[:20]}..." if token else "No token")

        # Supply details
        supply_url = f"{BASE_URL}/api/SupplyDetail/GetAll"
        supply_data = fetch_all(supply_url, token)
        print(f"Supply details count: {len(supply_data)}")

        # Transaction details
        trans_url = f"{BASE_URL}/api/TransactionDetail/GetAll"
        trans_data = fetch_all(trans_url, token)
        print(f"Transaction details count: {len(trans_data)}")

        # Group supply by product
        supply_totals = defaultdict(int)
        for item in supply_data:
            # Adjust field names as needed
            product_id = item.get('productId') or item.get('ProductId') or item.get('product_id')
            quantity = item.get('quantity') or item.get('Quantity') or item.get('qty') or 0
            if product_id is not None:
                try:
                    supply_totals[product_id] += int(quantity)
                except:
                    pass

        # Group transaction by product
        trans_totals = defaultdict(int)
        for item in trans_data:
            product_id = item.get('productId') or item.get('ProductId') or item.get('product_id')
            quantity = item.get('quantity') or item.get('Quantity') or item.get('qty') or 0
            if product_id is not None:
                try:
                    trans_totals[product_id] += int(quantity)
                except:
                    pass

        # Compute expected stock
        expected = {}
        for pid in set(list(supply_totals.keys()) + list(trans_totals.keys())):
            expected[pid] = supply_totals.get(pid, 0) - trans_totals.get(pid, 0)

        print(f"Expected stock for {len(expected)} products")

        # Fetch actual stock
        stock_url = f"{BASE_URL}/api/ProductLocationStock/GetAll"
        stock_data = fetch_all(stock_url, token)
        print(f"Stock details count: {len(stock_data)}")

        # Group actual stock by product (assuming ProductLocationStock has productId and quantity)
        actual_totals = defaultdict(int)
        for item in stock_data:
            product_id = item.get('productId') or item.get('ProductId') or item.get('product_id')
            quantity = item.get('quantity') or item.get('Quantity') or item.get('qty') or 0
            if product_id is not None:
                try:
                    actual_totals[product_id] += int(quantity)
                except:
                    pass

        # Compare
        mismatches = []
        all_pids = set(list(expected.keys()) + list(actual_totals.keys()))
        for pid in all_pids:
            exp = expected.get(pid, 0)
            act = actual_totals.get(pid, 0)
            if exp != act:
                mismatches.append((pid, exp, act))

        if mismatches:
            print("MISMATCHES FOUND:")
            for pid, exp, act in mismatches:
                print(f"Product {pid}: Expected {exp}, Actual {act}")
        else:
            print("All stock matches!")

    except Exception as e:
        print(f"Error: {e}")
        import traceback
        traceback.print_exc()

if __name__ == '__main__':
    main()
